import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A member of a pool with their share percent (two decimals): a person (memberPool null), retired when the person has
 *  a retirement date set, or another pool (memberPool its name, person 0); the membership's from-date and to-date (''
 *  when none) and whether they include the sheet's today (a member outside them is left out entirely); and their cut
 *  of the pool's pot (two decimals), '' when the pool is not balanced, has no pot or has only retired members, or the member is
 *  outside their dates. A pool in none has the sheet's pot; a pool in another has its cut there. */
export type PoolMember = {
  person: number;
  memberPool: string | null;
  name: string;
  share: string;
  retired: boolean;
  from: string;
  to: string;
  current: boolean;
  cut: string;
};

/** A pool: its members, the total of their shares (a retired member's counting as given, one outside their dates left out), and whether that is 100.00. */
export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean };

export const poolsKey = (sheet: string) => ['pools', sheet] as const;

export const poolsPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/pools`;

export const poolMembersPath = (sheet: string) => `/api/sheets/${encodeURIComponent(sheet)}/pool-members`;

/** The sheet's pools, in the order added. */
export function usePools(sheet: string) {
  return useQuery({
    queryKey: poolsKey(sheet),
    queryFn: () => getJson<Pool[]>(poolsPath(sheet)),
  });
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { byUser } from '../session/session';
import { usePeople } from '../people/people';
import { SheetPanels } from '../../slots/defs/sheetPanels';
import { poolMembersPath, poolsKey, poolsPath, usePools, type Pool } from './pools';
import { Fig } from '../locale/Fig';

// One pool's row: its members with their shares and cuts of the pot, its total share and whether it is balanced, and a form that adds
// a member chosen from the sheet's people or its other pools (pool:<name>).
function PoolRow({ sheet, user, pool, pools }: { sheet: string; user: string; pool: Pool; pools: Pool[] }) {
  const queryClient = useQueryClient();
  const { data: people = [] } = usePeople(sheet);
  // A person's id, or pool:<name> for another pool.
  const [member, setMember] = useState('');
  const [share, setShare] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');

  const add = useMutation({
    mutationFn: (body: {
      pool: string;
      person: number | null;
      memberPool: string | null;
      share: string;
      from: string;
      to: string;
    }) =>
      postJson<Pool[]>(byUser(poolMembersPath(sheet), user), body),
    onSuccess: (updated) => {
      queryClient.setQueryData(poolsKey(sheet), updated);
      setMember('');
      setShare('');
      setFrom('');
      setTo('');
    },
  });
  const send = useSubmitOnce(add);

  const submit = (e: FormEvent) => {
    e.preventDefault();
    // The server refuses a person already in the pool, a bad share, or a pool already in one, that would contain
    // itself, or would make a chain more than three deep, and a to-date before the from-date.
    const memberPool = member.startsWith('pool:') ? member.slice('pool:'.length) : null;
    const person = memberPool !== null || member === '' ? null : Number(member);
    send({ pool: pool.name, person, memberPool, share, from, to });
  };

  return (
    <li data-testid={`pool-row-${pool.name}`}>
      <strong>{pool.name}</strong> — total share <span data-testid="pool-total-share"><Fig>{pool.totalShare}</Fig></span>,
      balanced <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li
            key={m.memberPool !== null ? `pool:${m.memberPool}` : m.person}
            data-testid={`pool-member-${pool.name}-${m.memberPool !== null ? `pool-${m.memberPool}` : m.person}`}
          >
            {m.name} <span data-testid="pool-share"><Fig>{m.share}</Fig></span>%{m.retired ? ' (retired)' : ''}
            {m.from || m.to ? ` (${m.from || '…'} to ${m.to || '…'})` : ''}
            {m.current ? '' : ' (not current)'}, cut{' '}
            <span data-testid="pool-cut"><Fig>{m.cut}</Fig></span>
          </li>
        ))}
      </ul>
      <form onSubmit={submit}>
        <select
          data-testid="pool-member-select"
          value={member}
          onChange={(e) => {
            setMember(e.target.value);
            add.reset();
          }}
        >
          <option value="">Choose a member</option>
          {people.map((p) => (
            <option key={p.id} value={String(p.id)}>
              {p.name}
            </option>
          ))}
          {pools.map((p) => (
            <option key={`pool:${p.name}`} value={`pool:${p.name}`}>
              {`pool:${p.name}`}
            </option>
          ))}
        </select>{' '}
        <label>
          Share %{' '}
          <input
            data-testid="pool-member-share"
            value={share}
            onChange={(e) => {
              setShare(e.target.value);
              add.reset();
            }}
          />
        </label>{' '}
        <label>
          From{' '}
          <input
            type="date"
            data-testid="pool-member-from"
            value={from}
            onChange={(e) => {
              setFrom(e.target.value);
              add.reset();
            }}
          />
        </label>{' '}
        <label>
          To{' '}
          <input
            type="date"
            data-testid="pool-member-to"
            value={to}
            onChange={(e) => {
              setTo(e.target.value);
              add.reset();
            }}
          />
        </label>{' '}
        <button type="submit" data-testid="pool-member-add" disabled={add.isPending}>
          Add member
        </button>
        {add.isError && (
          <span data-testid="pool-error" role="alert">
            {' '}A member must not already be in the pool, and a share has two decimals, above 0.00 and at most
            100.00. A pool may be in at most one pool, never contain itself, and a chain of pools is at most three
            deep. A membership's to-date may not be before its from-date.
          </span>
        )}
      </form>
    </li>
  );
}

// The sheet's pools, and a form that adds one.
function Pools({ sheet, user }: { sheet: string; user: string }) {
  const queryClient = useQueryClient();
  const { data: pools = [] } = usePools(sheet);
